{
  "i18n": {
    "fr": {
      "confirm": "par le présent formulaire, je demande à ALCYON d'imprimer sur les étiquettes code-barres ALCYON un prix de vente indicatif TVAC calculé selon le tarif proposé par le fabricant (Aliments,...) ou, à défaut d'indications de celui-ci, en utilisant le coefficient de 1,45 + TVA par rapport au prix d'achat du tarif fabricant.",
      "Submit": "Envoyer",
      "required": "Ce champ est obligatoire."
    },
    "nl": {
      "confirm": "hierbij vraag ik aan ALCYON om op de barcode etiketten een indicatieve verkoopprijs incl. BTW te vermelden, die berekend wordt volgens het door de fabrikant voorgestelde tarief, of, bij gebreke daarvan, door toepassing van de coëfficiënt 1,45 + BTW ten opzichte van de aankoopprijs",
      "Submit": "Bevestig",
      "required": "Dit veld is verplicht."
    },
    "en": {
      "confirm": "by this request, I ask to ALCYON to print an informational selling price inc. VAT on the labels of my products. This price should correspond to the selling price proposed by the producer, and otherwise by applying a coefficient of 1,45 (+VAT) on the general selling price of the producer.",
      "Submit": "Submit",
      "required": "This field is mandatory."
    }
  }
}

